factory_as_code_schema.example:
apiVersion: factory.acme.dev/v1alpha1
kind: Factory
metadata: {name: engineering-default, owner: platform-eng}
spec:
  domain: engineering
  repository: {id: eng-repo, refPolicy: protected-main}
  triggers:
    - {type: github.issue.ready, dedupe: "$.delivery_id"}
  workflowRef: engineering/issue-to-pr@1.0.0
  actors:
    implementer: {identity: eng-impl, tools: [git,ci], permissions: [contents:write-branch]}
    verifier: {identity: eng-verify, independenceFrom: [implementer]}
  artifacts: {spec: schemas/eng-spec-1.json, patch: schemas/patch-1.json}
  gates:
    - {before: merge, policy: risk-tier, approvers: [CODEOWNERS], bindDigest: true}
  evals: {suite: evals/engineering-regression@7, promotion: no_safety_regression}
  improvement: {mode: propose_pr_only, protected: [policies/**, evals/hidden/**]}
---
apiVersion: factory.acme.dev/v1alpha1
kind: Factory
metadata: {name: gtm-campaign, owner: revenue-ops}
spec:
  enabled: false
  activationGate: {ref: decisions/gtm-activation.json, require: approved}
  domain: gtm
  repository: {id: gtm-repo, refPolicy: protected-main}
  workflowRef: gtm/research-to-measure@0.1.0
  policies: [privacy, consent, brand, claims, channel]
  gates:
    - {before: crm_write, approvers: [data-steward], bindDigest: true}
    - {before: publish_or_spend, approvers: [campaign-dri, brand-owner], bindDigest: true}
